        btn.addEventListener('click', () => { Snd.init(); Snd.pick(); openSel(b.dinner ? { type: 'dinner', date: sourceDate(b, date) } : { type: 'block', date: sourceDate(b, date), key: sourceKey(b) }); });
        li.appendChild(btn);
        ol.appendChild(li);
