      const at = M.dateTime(tr.r.date || M.dateTime(date, snapStart).date, tr.r.start == null ? M.dateTime(date, snapStart).start : tr.r.start);
      const shownStart = M.windowTime(date, at.date, at.start), h = M.visibleHours(state);
