    const tr = tryOn(() => { if (d.mode === 'wake') M.setWake(state, owner, v); else M.setBed(state, owner, v); return { ok: true, v: state.dates[owner][d.mode === 'wake' ? 'wake' : 'bed'] }; });
    const pd = daysWith(tr.dates, [date]);
