      if (b.meeting) return meetingPanel(p, b.meeting);
      if (b.event) return eventPanel(p, b.event);
      if (b.sleep) return dayPanel(p, sel.date);
      if (d.trip && /^trip/.test(b.tpl || '')) return eventPanel(p, d.trip.id);
