    if (sel.type === 'newIdea') return FEEL ? newIdeaFor(p, sel.kind, sel.group || 'partner', sel.who) : newIdeaPanel(p, sel.kind);
    if (sel.type === 'newPerson') return newPersonPanel(p, sel.group);
