      const setEveryLock = (on) => { commit(() => { if (tb) tb.fixed = on; if (dd.edits && dd.edits[b.tpl]) delete dd.edits[b.tpl].fixed; }); Snd.clack(0.5); toast(b.name + (on ? ' is locked every ' : ' is unlocked every ') + M.DAY_LONG[wd], 'good'); };
