    if (view.zoom === 'week' || view.zoom === 'day') { const at = boardTime(today, nowMin), tr = weekOf().indexOf(at.date); W.setNow(nowMin, tr >= 0 ? tr : null, info.soon, { weekMin: at.start, dayMin: view.focus === at.date ? at.start : null }); }
