      if (plan && plan.ok) { plan.text = why + ', so it goes at ' + M.clock(plan.start) + ', the closest time that fits. ' + plan.text; return plan; }
      return { add, date, start: want, ok: false, text: why + ', and nothing else fits that day.' };
