      const acts = el('div', 'quick-acts');
      const go = button(plan.ok ? 'Add to ' + (plan.date === today ? 'today' : M.DAY_LONG[M.weekday(plan.date)]) + ' at ' + M.clock(plan.start) : 'Pick another time', 'go', () => quickCommit(false));
      go.disabled = !plan.ok;
