      const w = u.w, d = u.dU, c = u.target, h = (u.h || 0.3) + 0.306;
      const a = px(c.x - w / 2 + 0.12, c.z - d / 2 + 0.2, h), b = px(c.x + w / 2 - 0.12, c.z + d / 2 - 0.2, h), a2 = px(c.x - w / 2 + 0.12, c.z + d / 2 - 0.2, h), b2 = px(c.x + w / 2 - 0.12, c.z - d / 2 + 0.2, h);
